--
-- Table structure for table `kids_english_card`
--

DROP TABLE IF EXISTS `kids_english_card`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `kids_english_card` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '卡片主键ID',
  `word` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '英文单词或词组',
  `translation` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '中文释义',
  `phonics` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `part_of_speech` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `level` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Core' COMMENT '学习难度：Core、Stretch 等',
  `syllables` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `stress` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phonics_focus` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `syllable_tip` text COLLATE utf8mb4_unicode_ci,
  `category` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '卡片分类',
  `emoji` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '卡片图示或 emoji',
  `image_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '帮助记忆的插画路径',
  `tip` text COLLATE utf8mb4_unicode_ci COMMENT '学习提示',
  `priority_order` int NOT NULL DEFAULT '0' COMMENT '排序值，越小越靠前',
  `is_active` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否启用：0-否，1-是',
  `created_by` bigint unsigned DEFAULT NULL COMMENT '创建人ID',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` bigint unsigned DEFAULT NULL COMMENT '修改人ID',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`),
  KEY `idx_kids_card_category` (`category`),
  KEY `idx_kids_card_level` (`level`),
  KEY `idx_kids_card_active_order` (`is_active`,`priority_order`),
  KEY `fk_kids_card_created_by` (`created_by`),
  KEY `fk_kids_card_updated_by` (`updated_by`),
  CONSTRAINT `fk_kids_card_created_by` FOREIGN KEY (`created_by`) REFERENCES `user` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_kids_card_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `user` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=249 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='儿童英语学习卡片主表';
/*!40101 SET character_set_client = @saved_cs_client */;

