--
-- Table structure for table `kids_english_card_sound_part`
--

DROP TABLE IF EXISTS `kids_english_card_sound_part`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `kids_english_card_sound_part` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '音节片段主键ID',
  `card_id` bigint unsigned NOT NULL COMMENT '儿童英语卡片ID',
  `part_order` int NOT NULL COMMENT '音节顺序，从1开始',
  `chunk` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '拼读片段，例如 play',
  `pronunciation` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '该片段发音，例如 /pleɪ/',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_kids_sound_card_order` (`card_id`,`part_order`),
  KEY `idx_kids_sound_card` (`card_id`),
  CONSTRAINT `fk_kids_sound_card` FOREIGN KEY (`card_id`) REFERENCES `kids_english_card` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=922 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='儿童英语卡片音节发音片段表';
/*!40101 SET character_set_client = @saved_cs_client */;

