-- Dumping data for table `kids_english_card_example`
--

LOCK TABLES `kids_english_card_example` WRITE;
/*!40000 ALTER TABLE `kids_english_card_example` DISABLE KEYS */;
INSERT INTO `kids_english_card_example` VALUES (281,1,'Harbin is in the northeast of China.','哈尔滨在中国的东北部。',1,1),(282,1,'Walk northeast for two blocks, and you will see the library.','向东北走两个街区，你会看到图书馆。',2,1),(283,2,'We built a sandcastle on the beach.','我们在海滩上堆了一个沙堡。',1,1),(284,2,'The beach is busy in summer.','夏天的海滩很热闹。',2,1),(285,3,'We had a wonderful time at the science museum.','我们在科学博物馆玩得很开心。',1,1),(286,3,'Your painting looks wonderful!','你的画看起来很棒！',2,1),(287,4,'Wear a helmet for your safety.','为了你的安全，请戴头盔。',1,1),(288,4,'Road safety is important for everyone.','道路安全对每个人都很重要。',2,1),(289,5,'Our class has a rule: be kind to everyone.','我们班有一条规则：要善待每一个人。',1,1),(290,5,'Please follow the rules in the library.','请遵守图书馆的规则。',2,1),(291,6,'Helping others can be meaningful.','帮助别人可以是一件有意义的事。',1,1),(292,6,'We had a meaningful talk about friendship.','我们就友谊进行了一次有意义的谈话。',2,1),(293,7,'The National Library of China has many old books.','中国国家图书馆有许多古老的书籍。',1,1),(294,7,'We visited the National Library of China last weekend.','上周末我们参观了中国国家图书馆。',2,1),(295,8,'I walk to school on foot.','我步行去学校。',1,1),(296,8,'The park is only ten minutes away on foot.','步行十分钟就能到公园。',2,1),(297,9,'We learned about space at the China Science and Technology Museum.','我们在中国科学技术馆学习了太空知识。',1,1),(298,9,'The China Science and Technology Museum is popular with children.','中国科学技术馆很受孩子们欢迎。',2,1),(299,10,'My home is far from school.','我家离学校很远。',1,1),(300,10,'The bus stop is not far from here.','公交车站离这里不远。',2,1),(301,11,'The baby is sleeping in the stroller.','宝宝正在婴儿车里睡觉。',1,1),(302,11,'The mother bird feeds her baby.','鸟妈妈在喂它的幼鸟。',2,1),(303,12,'The little chick follows its mother.','小鸡跟着妈妈走。',1,1),(304,12,'A yellow chick is pecking at seeds.','一只黄色小鸡正在啄种子。',2,1),(305,13,'I sometimes read before bed.','我有时睡前阅读。',1,1),(306,13,'It sometimes rains in the afternoon.','下午有时会下雨。',2,1),(307,14,'My father and I go fishing on Sundays.','我和爸爸星期天去钓鱼。',1,1),(308,14,'We went fishing by the lake.','我们在湖边钓鱼。',2,1),(309,15,'Owls sleep during the daytime.','猫头鹰在白天睡觉。',1,1),(310,15,'The stars are hard to see in the daytime.','白天很难看见星星。',2,1),(311,16,'My sister wants to study at a university.','我姐姐想去大学读书。',1,1),(312,16,'The university has a large library.','这所大学有一个很大的图书馆。',2,1),(313,17,'Toronto is the largest city in Canada.','多伦多是加拿大最大的城市。',1,1),(314,17,'My cousin lives in Toronto.','我表哥住在多伦多。',2,1),(315,18,'Ottawa is the capital of Canada.','渥太华是加拿大的首都。',1,1),(316,18,'The Parliament buildings are in Ottawa.','议会大厦在渥太华。',2,1),(317,19,'The doctor works at the hospital.','医生在医院工作。',1,1),(318,19,'We took Grandpa to the hospital.','我们带爷爷去了医院。',2,1),(319,20,'Please move your chair closer to the table.','请把椅子移近桌子。',1,1),(320,20,'The bus started to move.','公共汽车开始移动了。',2,1),(321,21,'He shook his head when he heard the bad news.','听到这个坏消息时，他摇了摇头。',1,1),(322,21,'Wear a hat to protect your head from the sun.','戴帽子保护头部免受阳光照射。',2,1),(323,22,'Always wear a helmet when you ride a bike.','骑自行车时一定要戴头盔。',1,1),(324,22,'His helmet is bright blue.','他的头盔是亮蓝色的。',2,1),(325,23,'Follow the path to the playground.','沿着小路走到操场。',1,1),(326,23,'Please follow your teacher.','请跟着老师走。',2,1),(327,24,'I stayed home because I had a stomachache.','我因为胃痛待在家里。',1,1),(328,24,'Too much candy can give you a stomachache.','吃太多糖会让你胃痛。',2,1),(329,25,'Do not touch the hot pan.','不要碰热锅。',1,1),(330,25,'The baby likes to touch soft toys.','宝宝喜欢摸柔软的玩具。',2,1),(331,26,'Please put the soup in a bowl.','请把汤盛在碗里。',1,1),(332,26,'There are apples in the blue bowl.','蓝色的碗里有苹果。',2,1),(333,27,'My teacher gave me good advice.','老师给了我很好的建议。',1,1),(334,27,'Thank you for your advice.','谢谢你的建议。',2,1),(335,28,'There is too much sugar in this drink.','这杯饮料里的糖太多。',1,1),(336,28,'Do not watch too much television.','不要看太多电视。',2,1),(337,29,'We ate dinner right after the game.','比赛结束后我们立刻吃了晚饭。',1,1),(338,29,'Call me right after school.','放学后立刻给我打电话。',2,1),(339,30,'Those flowers smell lovely.','那些花闻起来很香。',1,1),(340,30,'Who are those people by the gate?','大门旁边的那些人是谁？',2,1),(341,31,'Smoke can be a sign of fire.','烟可能是失火的信号。',1,1),(342,31,'Never play with fire.','绝不能玩火。',2,1),(343,32,'Water can turn into ice in cold weather.','天气寒冷时，水会变成冰。',1,1),(344,32,'The caterpillar will turn into a butterfly.','毛毛虫会变成蝴蝶。',2,1),(345,33,'Please light the candle carefully.','请小心点燃蜡烛。',1,1),(346,33,'The candle made the room feel warm.','蜡烛让房间感觉很温暖。',2,1),(347,34,'There is danger near the broken bridge.','破桥附近有危险。',1,1),(348,34,'The warning sign tells us about danger.','警示牌告诉我们有危险。',2,1),(349,35,'We like to talk after class.','我们喜欢课后聊天。',1,1),(350,35,'Please do not talk during the test.','考试期间请不要说话。',2,1),(351,36,'Use the exit in an emergency.','紧急情况下请使用出口。',1,1),(352,36,'The exit is next to the stairs.','出口在楼梯旁边。',2,1),(353,37,'Please come here right away.','请马上过来。',1,1),(354,37,'I will finish my homework right away.','我会立刻完成作业。',2,1),(355,38,'Cover the food before you put it in the fridge.','把食物放进冰箱前先盖好。',1,1),(356,38,'Dark clouds covered the sky.','乌云遮住了天空。',2,1),(357,39,'Take the lift to the sixth floor.','乘电梯到六楼。',1,1),(358,39,'The lift is beside the stairs.','电梯在楼梯旁边。',2,1),(359,40,'The firefighter helped the family leave safely.','消防员帮助这家人安全离开。',1,1),(360,40,'A firefighter wears special protective clothing.','消防员穿着特殊的防护服。',2,1),(361,41,'Use water to put out the campfire.','用水扑灭篝火。',1,1),(362,41,'The firefighters put out the fire quickly.','消防员很快扑灭了火。',2,1),(363,42,'Blow out the candle before you leave.','离开前吹灭蜡烛。',1,1),(364,42,'The wind can blow the leaves away.','风会把树叶吹走。',2,1),(365,43,'Would you like tea or juice?','你想要茶还是果汁？',1,1),(366,43,'You can walk or take the bus.','你可以步行或者乘公交车。',2,1),(367,44,'Would you like a cup of tea?','你想来一杯茶吗？',1,1),(368,44,'He drank a cup of milk.','他喝了一杯牛奶。',2,1),(369,45,'Do not go anywhere with a stranger.','不要跟陌生人去任何地方。',1,1),(370,45,'Tell an adult if a stranger talks to you.','如果陌生人和你说话，告诉一位成年人。',2,1),(371,46,'Exercise keeps your body strong.','锻炼使你的身体强壮。',1,1),(372,46,'Wash your hands to keep your body 